import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import axios from 'axios';

const SignupPage = () => {
  const [firstName, setFirstName] = useState('');
  const [lastName, setLastName] = useState('');
  const [username, setUsername] = useState('');
  const [password, setPassword] = useState('');
  const navigate = useNavigate();

  const handleSignup = async (e) => {
    e.preventDefault();
    try {
      await axios.post('http://localhost:5000/api/register', {
        firstName,
        lastName,
        username,
        password
      });
      navigate('/login');
    } catch (error) {
      console.error('Signup failed', error);
    }
  };

  return (
    <div 
      className="d-flex justify-content-center align-items-center vh-100" 
      style={{ 
        backgroundImage: 'linear-gradient(135deg, #FFDEE9 0%, #B5FFFC 100%)',
        color: '#fff',
        fontFamily: 'Arial, sans-serif'
      }}
    >
      <div 
        className="card p-5 shadow-lg" 
        style={{ 
          width: '400px', 
          backgroundColor: 'rgba(255, 255, 255, 0.9)', 
          borderRadius: '20px', 
          boxShadow: '0px 8px 15px rgba(0, 0, 0, 0.1)' 
        }}
      >
        <h2 className="text-center mb-4" style={{ color: '#444', fontWeight: '600' }}>Create Account</h2>
        <form onSubmit={handleSignup}>
          <div className="form-group mb-3">
            <label htmlFor="firstName" className="form-label" style={{ fontWeight: 'bold' }}>First Name</label>
            <input
              type="text"
              className="form-control"
              id="firstName"
              placeholder="Enter your first name"
              value={firstName}
              onChange={(e) => setFirstName(e.target.value)}
              style={{ borderRadius: '10px', padding: '10px' }}
            />
          </div>
          <div className="form-group mb-3">
            <label htmlFor="lastName" className="form-label" style={{ fontWeight: 'bold' }}>Last Name</label>
            <input
              type="text"
              className="form-control"
              id="lastName"
              placeholder="Enter your last name"
              value={lastName}
              onChange={(e) => setLastName(e.target.value)}
              style={{ borderRadius: '10px', padding: '10px' }}
            />
          </div>
          <div className="form-group mb-3">
            <label htmlFor="username" className="form-label" style={{ fontWeight: 'bold' }}>Username</label>
            <input
              type="text"
              className="form-control"
              id="username"
              placeholder="Enter your username"
              value={username}
              onChange={(e) => setUsername(e.target.value)}
              style={{ borderRadius: '10px', padding: '10px' }}
            />
          </div>
          <div className="form-group mb-4">
            <label htmlFor="password" className="form-label" style={{ fontWeight: 'bold' }}>Password</label>
            <input
              type="password"
              className="form-control"
              id="password"
              placeholder="Enter your password"
              value={password}
              onChange={(e) => setPassword(e.target.value)}
              style={{ borderRadius: '10px', padding: '10px' }}
            />
          </div>
          <button 
            type="submit" 
            className="btn btn-primary w-100 mb-3" 
            style={{ 
              backgroundColor: '#ff5e62', 
              border: 'none', 
              padding: '12px', 
              borderRadius: '10px', 
              fontWeight: 'bold',
              transition: 'background-color 0.3s ease' 
            }}
            onMouseEnter={(e) => e.target.style.backgroundColor = '#ff9966'}
            onMouseLeave={(e) => e.target.style.backgroundColor = '#ff5e62'}
          >
            Sign Up
          </button>
        </form>
        <div className="text-center">
          <p style={{ color: '#555' }}>Already have an account?</p>
          <button 
            className="btn btn-secondary" 
            style={{ 
              backgroundColor: '#4b79a1', 
              color: '#fff', 
              borderRadius: '10px',
              fontWeight: 'bold',
              padding: '10px 20px',
              transition: 'background-color 0.3s ease' 
            }}
            onMouseEnter={(e) => e.target.style.backgroundColor = '#283e51'}
            onMouseLeave={(e) => e.target.style.backgroundColor = '#4b79a1'}
            onClick={() => navigate('/login')}
          >
            Login
          </button>
        </div>
      </div>
    </div>
  );
};

export default SignupPage;
